#include "ConnectionDiagnosticsUI.h"
#include "UiLayout.h"
#include "lvgl_v8_port.h"
void ConnectionDiagnosticsUI::begin(BackCallback back) { lvgl_port_lock(-1); backCallback=back; const UiLayout l(profile); screen=lv_obj_create(nullptr); lv_obj_set_style_bg_color(screen,lv_color_hex(0x080C10),0); auto *t=lv_label_create(screen); lv_label_set_text(t,"CONNECTION DIAGNOSTICS"); lv_obj_align(t,LV_ALIGN_TOP_MID,0,l.y(30)); const char *names[]={"Wi-Fi","DCC-EX TCP","Roster","Turnouts","Routes"}; for(int i=0;i<5;++i){labels[i]=lv_label_create(screen);lv_obj_set_style_text_font(labels[i],&lv_font_montserrat_18,0);lv_obj_align(labels[i],LV_ALIGN_TOP_LEFT,l.x(68),l.y(100+i*48));lv_label_set_text_fmt(labels[i],"%s: loading",names[i]);} auto *b=lv_btn_create(screen);lv_obj_set_size(b,l.width(120),l.height(42));lv_obj_align(b,LV_ALIGN_BOTTOM_MID,0,-l.y(22));auto *bl=lv_label_create(b);lv_label_set_text(bl,"Back");lv_obj_center(bl);lv_obj_add_event_cb(b,backEvent,LV_EVENT_CLICKED,this);lvgl_port_unlock(); }
void ConnectionDiagnosticsUI::show(){if(!visible)returnScreen=lv_scr_act();visible=true;lv_scr_load(screen);} void ConnectionDiagnosticsUI::hide(){if(visible&&returnScreen)lv_scr_load(returnScreen);visible=false;}
void ConnectionDiagnosticsUI::update(bool wifi,bool tcp,bool roster,bool turnouts,bool routes){const bool v[]={wifi,tcp,roster,turnouts,routes};const char*n[]={"Wi-Fi","DCC-EX TCP","Roster","Turnouts","Routes"};for(int i=0;i<5;++i){lv_label_set_text_fmt(labels[i],"%s: %s",n[i],v[i]?"READY":"LOADING");lv_obj_set_style_text_color(labels[i],lv_color_hex(v[i]?0x35E06F:0xFFD740),0);}}
void ConnectionDiagnosticsUI::backEvent(lv_event_t *e){auto*u=static_cast<ConnectionDiagnosticsUI*>(lv_event_get_user_data(e));if(u->backCallback)u->backCallback();}
